package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class AppearanceConfigTest {
    private final String section="b8348b88-aac9-4f3c-85f7-bb44b7e2b967";
    @Test public void roundtripPreservesUnicodeAndBothPalettes(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Preset p=new AppearanceConfig.Preset();p.name="Тема 👨‍👩‍👧";p.style.color(false,"chat_outBubble",123);p.style.color(true,"chat_outBubble",456);c.presets.put(p.id,p);c.apply("chat:-123",p);AppearanceConfig d=AppearanceConfig.decode(c.encode());assertEquals(p.name,d.presets.get(p.id).name);assertEquals(Integer.valueOf(456),d.resolve(AppearanceConfig.Context.direct(-123,0)).color(true,"chat_outBubble"));}
    @Test public void inheritanceIsPerPropertyAndResetRestoresParent(){AppearanceConfig c=new AppearanceConfig();c.edit("global").set("x","global");c.edit("section:"+section).set("x","section");c.edit("folder:tg:17").set("y","folder");c.edit("chat:-5").set("x","chat");c.edit("topic:-5:77").set("y","topic");AppearanceConfig.Context ctx=new AppearanceConfig.Context(section,"tg:17",-5,77);assertEquals("chat",c.resolve(ctx).get("x"));assertEquals("topic",c.resolve(ctx).get("y"));assertEquals("chat:-5",c.resolve(ctx).origins.get("x"));c.reset("chat:-5");assertEquals("section",c.resolve(ctx).get("x"));}
    @Test public void directSearchAndNotificationDoNotPickRandomFolder(){AppearanceConfig c=new AppearanceConfig();c.edit("global").set("x","global");c.edit("folder:tg:17").set("x","folder");assertEquals("global",c.resolve(AppearanceConfig.Context.direct(3,0)).get("x"));assertEquals("folder",c.resolve(new AppearanceConfig.Context(null,"tg:17",3,0)).get("x"));}
    @Test public void chatsAndAccountsAreIndependent(){AppearanceConfig a=new AppearanceConfig(),b=new AppearanceConfig();a.edit("chat:5").set("x","one");assertNull(a.resolve(AppearanceConfig.Context.direct(6,0)).get("x"));assertNull(b.resolve(AppearanceConfig.Context.direct(5,0)).get("x"));assertNotEquals(AppearanceConfig.accountDirectory(5),AppearanceConfig.accountDirectory(6));}
    @Test public void oneFolderInTwoSectionsHasSameExplicitFolderOverride(){AppearanceConfig c=new AppearanceConfig();String other="b8348b88-aac9-4f3c-85f7-bb44b7e2b968";c.edit("section:"+section).set("x","a");c.edit("section:"+other).set("x","b");c.edit("folder:tg:17").set("x","f");assertEquals("f",c.resolve(new AppearanceConfig.Context(section,"tg:17",4,0)).get("x"));assertEquals("f",c.resolve(new AppearanceConfig.Context(other,"tg:17",4,0)).get("x"));}
    @Test public void applyingAndDuplicatingNeverShareMutableStyle(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Preset p=AppearancePresets.builtins().get(0);c.apply("chat:1",p);AppearanceConfig.Preset q=p.duplicate("Copy");q.style.set("x","changed");c.edit("chat:1").set("x","chat");assertNull(p.style.values.get("x"));assertNotEquals(p.id,q.id);}
    @Test public void mediaReferencesIncludeInactivePresets(){AppearanceConfig c=new AppearanceConfig();AppearanceConfig.Preset p=new AppearanceConfig.Preset();String file=UUID.randomUUID()+".mp4";p.style.set("wallpaper.file",file);c.presets.put(p.id,p);c.edit("chat:1").set("wallpaper.file",file);assertEquals(Collections.singleton(file),c.mediaReferences());c.reset("chat:1");assertTrue(c.mediaReferences().contains(file));c.presets.clear();assertTrue(c.mediaReferences().isEmpty());}
    @Test public void noExistingSectionMigrationOrSessionStorageIsNeeded(){AppearanceConfig c=AppearanceConfig.decode("");assertTrue(c.scopes.isEmpty());assertTrue(c.presets.isEmpty());assertEquals(0,c.revision);}
    @Test(expected=IllegalArgumentException.class) public void rejectsFutureSchema(){AppearanceConfig.decode("schema=999");}
    @Test(expected=IllegalArgumentException.class) public void rejectsUnsafeScope(){new AppearanceConfig().edit("folder:../../session");}
    @Test public void mediaNamesRejectTraversalAndAbsolutePaths(){assertFalse(AppearanceConfig.isMediaName("../a.mp4"));assertFalse(AppearanceConfig.isMediaName("/data/a.png"));assertTrue(AppearanceConfig.isMediaName(UUID.randomUUID()+".jpg"));}
    @Test public void builtinsProvideBothPalettesWithReadableText(){assertEquals(7,AppearancePresets.builtins().size());for(AppearanceConfig.Preset p:AppearancePresets.builtins())for(boolean dark:new boolean[]{false,true}){AppearanceConfig c=new AppearanceConfig();c.apply("global",p);AppearanceConfig.Resolved r=c.resolve(AppearanceConfig.Context.direct(0,0));assertTrue(AppearancePresets.ratio(r.color(dark,"chat_outBubble"),r.color(dark,"chat_messageTextOut"))>=4.5);assertTrue(AppearancePresets.ratio(r.color(dark,"chats_actionBackground"),r.color(dark,"chats_actionIcon"))>=4.5);assertTrue(AppearancePresets.ratio(r.color(dark,"chats_unreadCounter"),r.color(dark,"chats_unreadCounterText"))>=4.5);}}
    @Test public void groupCanChooseGlobalOrTelegramWallpaperWithoutLosingOtherInheritance(){AppearanceConfig c=new AppearanceConfig();c.edit("global").set("wallpaper.file","global");c.edit("section:"+section).set("wallpaper.file","section");c.edit("section:"+section).set("accent","section");c.edit("chat:-5").set("wallpaper.base","global");AppearanceConfig.Context ctx=new AppearanceConfig.Context(section,null,-5,0);assertEquals("global",c.resolve(ctx).get("wallpaper.file"));assertEquals("section",c.resolve(ctx).get("accent"));c.edit("chat:-5").set("wallpaper.base","telegram");assertNull(c.resolve(ctx).get("wallpaper.file"));c.edit("chat:-5").values.remove("wallpaper.base");assertEquals("section",c.resolve(ctx).get("wallpaper.file"));}
}
